enum class Status { Waiting, Answered, Failed };

class UdpQuery
{
public:
    UdpQuery(Endpoint server, std::uint16_t id, int attempts, std::uint64_t firstTimeout) {}
    std::uint64_t start(std::uint64_t now) { return now; }
    std::optional<std::uint64_t> onTimer(std::uint64_t now) { return std::nullopt; }
    void onDatagram(Endpoint from, const std::vector<std::uint8_t>& data, std::uint64_t now) {}
    Status status() const { return Status::Waiting; }
    int sends() const { return 0; }
    std::vector<std::uint8_t> answer() const { return {}; }
};

solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <vector>

struct Endpoint { std::uint32_t address; std::uint16_t port; };
enum class Status { Waiting, Answered, Failed };

class UdpQuery
{
public:
    UdpQuery(Endpoint server, std::uint16_t id, int attempts, std::uint64_t firstTimeout)
        : server{ server }, id{ id }, attempts{ attempts }, timeout{ firstTimeout } {}

    std::uint64_t start(std::uint64_t now)
    {
        count = 1;
        return now + timeout;
    }

    std::optional<std::uint64_t> onTimer(std::uint64_t now)
    {
        if (state != Status::Waiting) return std::nullopt;
        if (count >= attempts) { state = Status::Failed; return std::nullopt; }
        ++count;
        timeout *= 2;
        return now + timeout;
    }

    void onDatagram(Endpoint from, const std::vector<std::uint8_t>& data, std::uint64_t)
    {
        if (state != Status::Waiting || from.address != server.address || from.port != server.port) return;
        if (data.size() < 2 || ((data[0] << 8) | data[1]) != id) return;
        reply.assign(data.begin() + 2, data.end());
        state = Status::Answered;
    }

    Status status() const { return state; }
    int sends() const { return count; }
    std::vector<std::uint8_t> answer() const { return reply; }

private:
    Endpoint server;
    std::uint16_t id;
    int attempts;
    std::uint64_t timeout;
    int count{ 0 };
    Status state{ Status::Waiting };
    std::vector<std::uint8_t> reply;
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
static const Endpoint SERVER{ 0x08080808, 53 };
TEST("answered on the first try") {
    UdpQuery q{ SERVER, 0xBEEF, 3, 500 };
    CHECK_EQ(q.start(1000), 1500ull);
    q.onDatagram(SERVER, { 0xBE, 0xEF, 1, 2, 3 }, 1020);
    CHECK(q.status() == Status::Answered);
    CHECK(q.answer() == (Bytes{ 1, 2, 3 }));
    CHECK(!q.onTimer(1500).has_value());
    CHECK_EQ(q.sends(), 1);
}
TEST("retries with doubling timeouts, then failure") {
    UdpQuery q{ SERVER, 7, 3, 500 };
    const std::uint64_t first{ q.start(0) };
    const auto second{ q.onTimer(first) };
    CHECK_EQ(second.value_or(0), 1500ull);
    const auto third{ q.onTimer(*second) };
    CHECK_EQ(third.value_or(0), 3500ull);
    CHECK(!q.onTimer(*third).has_value());
    CHECK(q.status() == Status::Failed);
    CHECK_EQ(q.sends(), 3);
    q.onDatagram(SERVER, { 0, 7, 9 }, 4000);
    CHECK(q.status() == Status::Failed);
}
TEST("forged and stray answers are ignored") {
    UdpQuery q{ SERVER, 0x1234, 3, 500 };
    q.start(0);
    q.onDatagram({ 0x01020304, 53 }, { 0x12, 0x34, 6, 6, 6 }, 10);
    q.onDatagram({ 0x08080808, 5353 }, { 0x12, 0x34, 6, 6, 6 }, 11);
    q.onDatagram(SERVER, { 0x12, 0x35, 6 }, 12);
    q.onDatagram(SERVER, { 0x12 }, 13);
    CHECK(q.status() == Status::Waiting);
    q.onDatagram(SERVER, { 0x12, 0x34 }, 14);
    CHECK(q.status() == Status::Answered);
    CHECK(q.answer().empty());
    q.onDatagram(SERVER, { 0x12, 0x34, 9 }, 15);
    CHECK(q.answer().empty());
}

